PRAGMA foreign_keys=ON;
CREATE TABLE games(app_id INTEGER PRIMARY KEY CHECK(app_id>0),name TEXT NOT NULL,metadata_available INTEGER NOT NULL CHECK(metadata_available IN(0,1)),review_group TEXT NOT NULL,eligible INTEGER NOT NULL CHECK(eligible IN(0,1)));
CREATE TABLE game_genres(app_id INTEGER NOT NULL REFERENCES games(app_id),genre TEXT NOT NULL,PRIMARY KEY(app_id,genre));
CREATE TABLE sources(source_id INTEGER PRIMARY KEY,name TEXT NOT NULL,path TEXT NOT NULL,sha256 TEXT NOT NULL,url TEXT NOT NULL,licence_note TEXT NOT NULL,rows INTEGER NOT NULL);
CREATE TABLE source_observations(app_id INTEGER NOT NULL REFERENCES games(app_id),month TEXT NOT NULL CHECK(length(month)=10 AND substr(month,9,2)='01'),avg_players REAL NOT NULL CHECK(avg_players>=0 AND avg_players<1e308),source_id INTEGER NOT NULL REFERENCES sources(source_id),priority INTEGER NOT NULL,source_url TEXT NOT NULL,PRIMARY KEY(source_id,app_id,month));
CREATE TABLE monthly_players(app_id INTEGER NOT NULL REFERENCES games(app_id),month TEXT NOT NULL CHECK(length(month)=10 AND substr(month,9,2)='01'),avg_players REAL NOT NULL CHECK(avg_players>=0 AND avg_players<1e308),source_id INTEGER NOT NULL REFERENCES sources(source_id),priority INTEGER NOT NULL,source_url TEXT NOT NULL,PRIMARY KEY(app_id,month));
CREATE TABLE cohort_membership(app_id INTEGER PRIMARY KEY REFERENCES games(app_id),name TEXT NOT NULL,metadata_available INTEGER NOT NULL,review_group TEXT NOT NULL,eligible INTEGER NOT NULL,observed_window_months INTEGER NOT NULL,cohort_reason TEXT NOT NULL,in_cohort INTEGER NOT NULL CHECK(in_cohort IN(0,1)));
CREATE TABLE category_monthly(category TEXT NOT NULL,month TEXT NOT NULL,avg_players REAL NOT NULL CHECK(avg_players>=0 AND avg_players<1e308),observed_apps INTEGER NOT NULL CHECK(observed_apps>0),PRIMARY KEY(category,month));
